# The film's small sounds: MacBook key presses and a trackpad click, cut from ElevenLabs takes in
# raw/cand/ (generated by gen-keys.ts). Each take is high-passed (no desk thump), cut to its one
# transient, faded out with no room left on it, and set against the tape's speech level: keys sit
# 20 dB under the voice, the trackpad 27 dB under. Writes public/show/audio/sfx-key-N.mp3 and
# sfx-tap.mp3 and their entries in manifest.json; process.py calls build() too.
# uv run -q --with numpy python keys.py
import json, os, subprocess, wave
import numpy as np

SR = 44100
here = os.path.dirname(os.path.abspath(__file__))
CAND = os.path.join(here, "raw", "cand")
OUT = os.path.join(here, "../../public/show/audio")
# take, kind: six keys (rotated in audio.js so no two presses in a row match) and one click
TAKES = [("kb0", "key"), ("kc0", "key"), ("kc2", "key"), ("kd2", "key"), ("ka2", "key"), ("kb2", "key"), ("tp1", "tap")]
UNDER = {"key": 20, "tap": 27}


def load(path):
    raw = subprocess.run(["ffmpeg", "-v", "quiet", "-i", path, "-ac", "1", "-ar", str(SR), "-f", "f32le", "-"], capture_output=True, check=True).stdout
    return np.frombuffer(raw, dtype=np.float32).astype(np.float64)


def biquad(x, fc, high):
    w = 2 * np.pi * fc / SR
    a, c = np.sin(w) / (2 * 0.707), np.cos(w)
    b = np.array([(1 + c) / 2, -(1 + c), (1 + c) / 2]) if high else np.array([(1 - c) / 2, 1 - c, (1 - c) / 2])
    a0, a1, a2 = 1 + a, -2 * c, 1 - a
    b, a1, a2 = b / a0, a1 / a0, a2 / a0
    y = np.zeros_like(x)
    x1 = x2 = y1 = y2 = 0.0
    for i, v in enumerate(x):
        o = b[0] * v + b[1] * x1 + b[2] * x2 - a1 * y1 - a2 * y2
        x2, x1, y2, y1 = x1, v, y1, o
        y[i] = o
    return y


def env(x, win=110):
    return np.sqrt(np.convolve(x * x, np.ones(win) / win, mode="same"))


def cut(x, kind):
    hp, lp, length, fade = (350, 11000, 0.075, 0.045) if kind == "key" else (500, 9000, 0.055, 0.035)
    y = biquad(biquad(biquad(x, hp, True), hp, True), lp, False)
    e = env(y)
    ip = int(np.argmax(e))
    th, o = e[ip] * 10 ** (-26 / 20), ip
    while o > 0 and e[o] > th:
        o -= 1
    o = max(0, o - int(0.002 * SR))
    n = int(length * SR)
    seg = np.pad(y[o : o + n], (0, max(0, n - len(y[o : o + n]))))
    k = int(0.001 * SR)
    seg[:k] *= np.linspace(0, 1, k)
    f = int(fade * SR)
    t = np.linspace(0, 1, f)
    seg[-f:] *= np.exp(-5 * t) * (1 - t)
    return seg


def speech_rms(path):
    x = load(path)
    n = 2205
    r = np.sqrt((x[: len(x) // n * n].reshape(-1, n) ** 2).mean(1))
    db = 20 * np.log10(r + 1e-9)
    a = db[db > db.max() - 25]
    return 20 * np.log10(np.sqrt((10 ** (a / 10)).mean()))


def build(manifest):
    voice = speech_rms(os.path.join(OUT, manifest["voice"]["tape"]["takes"][0]["file"]))
    keys = []
    for take, kind in TAKES:
        seg = cut(load(os.path.join(CAND, take + ".mp3")), kind)
        # level by the loudest 30 ms, the part you hear
        loud = 20 * np.log10(env(seg, int(0.03 * SR)).max())
        seg *= 10 ** ((voice - UNDER[kind] - loud) / 20)
        name = f"sfx-key-{len(keys) + 1}.mp3" if kind == "key" else "sfx-tap.mp3"
        tmp = os.path.join(OUT, name + ".wav")
        with wave.open(tmp, "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(SR)
            w.writeframes((np.clip(np.concatenate([seg, np.zeros(int(0.01 * SR))]), -1, 1) * 32767).astype(np.int16).tobytes())
        subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", tmp, "-ac", "1", "-ar", "44100", "-b:a", "96k", os.path.join(OUT, name)], check=True)
        os.remove(tmp)
        if kind == "key":
            keys.append(name)
        else:
            manifest["sfx"]["tap"] = name
    manifest["sfx"]["key"] = {"variants": keys}
    return manifest


if __name__ == "__main__":
    mf = os.path.join(OUT, "manifest.json")
    m = json.load(open(mf))
    for gone in ("thunk", "close", "shutter", "key2"):
        m["sfx"].pop(gone, None)
        p = os.path.join(OUT, f"sfx-{gone}.mp3")
        if os.path.exists(p):
            os.remove(p)
    old = os.path.join(OUT, "sfx-key.mp3")
    if os.path.exists(old):
        os.remove(old)
    json.dump(build(m), open(mf, "w"))
    print("keys", m["sfx"]["key"], "tap", m["sfx"]["tap"])
